'use strict';

/**
 * Compact factory for comparison catalog entries.
 * Values are indicative for deterministic comparison; free-text colleges
 * can be resolved via AI and cached separately.
 */
function c(entry) {
  return {
    ownership: 'Private',
    approvals: ['AICTE'],
    rankingLabel: entry.rankingLabel || 'Established institute',
    rankingScore: entry.rankingScore ?? 60,
    averagePackageLabel: entry.averagePackageLabel || `${entry.averagePackageValue} LPA`,
    placementRateLabel: entry.placementRateLabel || `${entry.placementRateValue}%`,
    annualFeesLabel: entry.annualFeesLabel || `₹${entry.annualFeesValue}L / yr`,
    roiLabel: entry.roiLabel || 'Balanced ROI',
    roiScore: entry.roiScore ?? 65,
    campusSizeLabel: entry.campusSizeLabel || 'Medium campus',
    campusSizeScore: entry.campusSizeScore ?? 60,
    branchCount: entry.branchCount ?? 4,
    flagshipBranches: entry.flagshipBranches || ['CSE', 'ECE', 'EEE', 'Mechanical'],
    highlights: entry.highlights || ['Popular among aspirants', 'Known regional brand'],
    aliases: entry.aliases || [],
    shortName: entry.shortName || entry.name,
    ...entry,
  };
}

